window.QURAN={"order":[1,114,113,112,111,110,109,108,107,106,105,104,103,102,101,100,99,98,97,96,95,94,93,92,91,90,89,88,87,86,85,84,83,82,81,80,79,78],"bsm":"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","q":{"1":{"n":1,"name":"Al-Fātiḥah","ar":"الفاتحة","en":"The Opening","v":[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","In the Name of Allah, the Most Compassionate, Most Merciful."],[2,"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","All praise is for Allah, Lord of all worlds,"],[3,"ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","the Most Compassionate, Most Merciful,"],[4,"مَـٰلِكِ يَوْمِ ٱلدِّينِ","Master of the Day of Judgment."],[5,"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","You ˹alone˺ we worship and You ˹alone˺ we ask for help."],[6,"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","Guide us along the Straight Path,"],[7,"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","the Path of those You have blessed, not those You are displeased with, or those who are astray."]]},"78":{"n":78,"name":"An-Nabaʾ","ar":"النبإ","en":"The Momentous News","v":[[1,"عَمَّ يَتَسَآءَلُونَ","What are they asking one another about?"],[2,"عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ","About the momentous news,"],[3,"ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ","over which they disagree."],[4,"كَلَّا سَيَعْلَمُونَ","But no! They will come to know."],[5,"ثُمَّ كَلَّا سَيَعْلَمُونَ","Again, no! They will come to know."],[6,"أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًۭا","Have We not smoothed out the earth ˹like a bed˺,"],[7,"وَٱلْجِبَالَ أَوْتَادًۭا","and ˹made˺ the mountains as ˹its˺ pegs,"],[8,"وَخَلَقْنَـٰكُمْ أَزْوَٰجًۭا","and created you in pairs,"],[9,"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا","and made your sleep for rest,"],[10,"وَجَعَلْنَا ٱلَّيْلَ لِبَاسًۭا","and made the night as a cover,"],[11,"وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًۭا","and made the day for livelihood,"],[12,"وَبَنَيْنَا فَوْقَكُمْ سَبْعًۭا شِدَادًۭا","and built above you seven mighty ˹heavens˺,"],[13,"وَجَعَلْنَا سِرَاجًۭا وَهَّاجًۭا","and placed ˹in them˺ a shining lamp,"],[14,"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا","and sent down from rainclouds pouring water,"],[15,"لِّنُخْرِجَ بِهِۦ حَبًّۭا وَنَبَاتًۭا","producing by it grain and ˹various˺ plants,"],[16,"وَجَنَّـٰتٍ أَلْفَافًا","and dense orchards?"],[17,"إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًۭا","Indeed, the Day of ˹Final˺ Decision is an appointed time,"],[18,"يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا","˹it is˺ the Day the Trumpet will be blown, and you will ˹all˺ come forth in crowds."],[19,"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا","The sky will be ˹split˺ open, becoming ˹many˺ gates,"],[20,"وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا","and the mountains will be blown away, becoming ˹like˺ a mirage."],[21,"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا","Indeed, Hell is lying in ambush"],[22,"لِّلطَّـٰغِينَ مَـَٔابًۭا","as a home for the transgressors,"],[23,"لَّـٰبِثِينَ فِيهَآ أَحْقَابًۭا","where they will remain for ˹endless˺ ages."],[24,"لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا","There they will not taste any coolness or drink,"],[25,"إِلَّا حَمِيمًۭا وَغَسَّاقًۭا","except boiling water and ˹oozing˺ pus,"],[26,"جَزَآءًۭ وِفَاقًا","a fitting reward."],[27,"إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا","For they never expected any reckoning,"],[28,"وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا كِذَّابًۭا","and totally rejected Our signs."],[29,"وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ كِتَـٰبًۭا","And We have everything recorded precisely."],[30,"فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا","˹So the deniers will be told,˺ “Taste ˹the punishment˺, for all you will get from Us is more torment.”"],[31,"إِنَّ لِلْمُتَّقِينَ مَفَازًا","Indeed, the righteous will have salvation,"],[32,"حَدَآئِقَ وَأَعْنَـٰبًۭا","Gardens, vineyards,"],[33,"وَكَوَاعِبَ أَتْرَابًۭا","and full-bosomed maidens of equal age,"],[34,"وَكَأْسًۭا دِهَاقًۭا","and full cups ˹of pure wine˺,"],[35,"لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا","never to hear any idle talk or lying therein ,"],[36,"جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا","a ˹fitting˺ reward as a generous gift from your Lord,"],[37,"رَّبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَـٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا","the Lord of the heavens and the earth and everything in between, the Most Compassionate. No one will dare speak to Him"],[38,"يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَـٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَابًۭا","on the Day the ˹holy˺ spirit and the angels will stand in ranks. None will talk, except those granted permission by the Most Compassionate and whose words are true."],[39,"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","That Day is the ˹ultimate˺ truth. So let whoever wills take the path leading back to their Lord."],[40,"إِنَّآ أَنذَرْنَـٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَـٰلَيْتَنِى كُنتُ تُرَٰبًۢا","Indeed, We have warned you of an imminent punishment, the Day every person will see ˹the consequences of˺ what their hands have done, and the disbelievers will cry, “I wish I were dust.”"]]},"79":{"n":79,"name":"An-Nāziʿāt","ar":"النازعات","en":"Those ˹Angels˺ Stripping out ˹Souls˺","v":[[1,"وَٱلنَّـٰزِعَـٰتِ غَرْقًۭا","By those ˹angels˺ stripping out ˹evil souls˺ harshly,"],[2,"وَٱلنَّـٰشِطَـٰتِ نَشْطًۭا","and those pulling out ˹good souls˺ gently,"],[3,"وَٱلسَّـٰبِحَـٰتِ سَبْحًۭا","and those gliding ˹through heavens˺ swiftly,"],[4,"فَٱلسَّـٰبِقَـٰتِ سَبْقًۭا","and those taking the lead vigorously,"],[5,"فَٱلْمُدَبِّرَٰتِ أَمْرًۭا","and those conducting affairs ˹obediently˺!"],[6,"يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ","˹Consider˺ the Day ˹when˺ the quaking Blast will come to pass,"],[7,"تَتْبَعُهَا ٱلرَّادِفَةُ","followed by a second Blast."],[8,"قُلُوبٌۭ يَوْمَئِذٍۢ وَاجِفَةٌ","˹The deniers’˺ hearts on that Day will be trembling ˹in horror˺,"],[9,"أَبْصَـٰرُهَا خَـٰشِعَةٌۭ","with their eyes downcast."],[10,"يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ","˹But now˺ they ask ˹mockingly˺, “Will we really be restored to our former state,"],[11,"أَءِذَا كُنَّا عِظَـٰمًۭا نَّخِرَةًۭ","even after we have been reduced to decayed bones?”"],[12,"قَالُوا۟ تِلْكَ إِذًۭا كَرَّةٌ خَاسِرَةٌۭ","Adding, “Then such a return would be a ˹total˺ loss ˹for us˺!”"],[13,"فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ","But indeed, it will take only one ˹mighty˺ Blast,"],[14,"فَإِذَا هُم بِٱلسَّاهِرَةِ","and at once they will be above ground."],[15,"هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","Has the story of Moses reached you ˹O Prophet˺?"],[16,"إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى","His Lord called him in the sacred valley of Ṭuwa,"],[17,"ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","˹commanding,˺ “Go to Pharaoh, for he has truly transgressed ˹all bounds˺."],[18,"فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","And say, ‘Would you ˹be willing to˺ purify yourself,"],[19,"وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","and let me guide you to your Lord so that you will be in awe ˹of Him˺?’”"],[20,"فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ","Then Moses showed him the great sign,"],[21,"فَكَذَّبَ وَعَصَىٰ","but he denied and disobeyed ˹Allah˺,"],[22,"ثُمَّ أَدْبَرَ يَسْعَىٰ","then turned his back, striving ˹against the truth˺."],[23,"فَحَشَرَ فَنَادَىٰ","Then he summoned ˹his people˺ and called out,"],[24,"فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ","saying, “I am your lord, the most high!”"],[25,"فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ","So Allah overtook him, making him an example in this life and the next."],[26,"إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ","Surely in this is a lesson for whoever stands in awe of ˹Allah˺."],[27,"ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا","Which is harder to create: you or the sky? He built it,"],[28,"رَفَعَ سَمْكَهَا فَسَوَّىٰهَا","raising it high and forming it flawlessly."],[29,"وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا","He dimmed its night, and brought forth its daylight."],[30,"وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ","As for the earth, He spread it out as well,"],[31,"أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا","bringing forth its water and pastures"],[32,"وَٱلْجِبَالَ أَرْسَىٰهَا","and setting the mountains firmly ˹upon it˺,"],[33,"مَتَـٰعًۭا لَّكُمْ وَلِأَنْعَـٰمِكُمْ","all as ˹a means of˺ sustenance for you and your animals."],[34,"فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ","But, when the Supreme Disaster comes to pass,"],[35,"يَوْمَ يَتَذَكَّرُ ٱلْإِنسَـٰنُ مَا سَعَىٰ","the Day every person will remember all ˹their˺ striving,"],[36,"وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ","and the Hellfire will be displayed for all to see,"],[37,"فَأَمَّا مَن طَغَىٰ","then as for those who transgressed"],[38,"وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","and preferred the ˹fleeting˺ life of this world,"],[39,"فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ","the Hellfire will certainly be ˹their˺ home."],[40,"وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ","And as for those who were in awe of standing before their Lord and restrained themselves from ˹evil˺ desires,"],[41,"فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ","Paradise will certainly be ˹their˺ home."],[42,"يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا","They ask you ˹O Prophet˺ regarding the Hour, “When will it be?”"],[43,"فِيمَ أَنتَ مِن ذِكْرَىٰهَآ","But it is not for you to tell its time."],[44,"إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","That knowledge rests with your Lord ˹alone˺."],[45,"إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا","Your duty is only to warn whoever is in awe of it."],[46,"كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا","On the Day they see it, it will be as if they had stayed ˹in the world˺ no more than one evening or its morning."]]},"80":{"n":80,"name":"ʿAbasa","ar":"عبس","en":"He Frowned","v":[[1,"عَبَسَ وَتَوَلَّىٰٓ","He frowned and turned ˹his attention˺ away,"],[2,"أَن جَآءَهُ ٱلْأَعْمَىٰ","˹simply˺ because the blind man came to him ˹interrupting˺."],[3,"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","You never know ˹O Prophet˺, perhaps he may be purified,"],[4,"أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ","or he may be mindful, benefitting from the reminder."],[5,"أَمَّا مَنِ ٱسْتَغْنَىٰ","As for the one who was indifferent,"],[6,"فَأَنتَ لَهُۥ تَصَدَّىٰ","you gave him your ˹undivided˺ attention,"],[7,"وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ","even though you are not to blame if he would not be purified."],[8,"وَأَمَّا مَن جَآءَكَ يَسْعَىٰ","But as for the one who came to you, eager ˹to learn˺,"],[9,"وَهُوَ يَخْشَىٰ","being in awe ˹of Allah˺,"],[10,"فَأَنتَ عَنْهُ تَلَهَّىٰ","you were inattentive to him."],[11,"كَلَّآ إِنَّهَا تَذْكِرَةٌۭ","But no! This ˹revelation˺ is truly a reminder."],[12,"فَمَن شَآءَ ذَكَرَهُۥ","So let whoever wills be mindful of it."],[13,"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ","It is ˹written˺ on pages held in honour,"],[14,"مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ","highly esteemed, purified,"],[15,"بِأَيْدِى سَفَرَةٍۢ","by the hands of angel-scribes,"],[16,"كِرَامٍۭ بَرَرَةٍۢ","honourable and virtuous."],[17,"قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ","Condemned are ˹disbelieving˺ humans! How ungrateful they are ˹to Allah˺!"],[18,"مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ","From what substance did He create them?"],[19,"مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","He created them from a sperm-drop, and ordained their development."],[20,"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","Then He makes the way easy for them,"],[21,"ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ","then causes them to die and be buried."],[22,"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","Then when He wills, He will resurrect them."],[23,"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ","But no! They have failed to comply with what He ordered."],[24,"فَلْيَنظُرِ ٱلْإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ","Let people then consider their food:"],[25,"أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا","how We pour down rain in abundance"],[26,"ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا","and meticulously split the earth open ˹for sprouts˺,"],[27,"فَأَنۢبَتْنَا فِيهَا حَبًّۭا","causing grain to grow in it,"],[28,"وَعِنَبًۭا وَقَضْبًۭا","as well as grapes and greens,"],[29,"وَزَيْتُونًۭا وَنَخْلًۭا","and olives and palm trees,"],[30,"وَحَدَآئِقَ غُلْبًۭا","and dense orchards,"],[31,"وَفَـٰكِهَةًۭ وَأَبًّۭا","and fruit and fodder,"],[32,"مَّتَـٰعًۭا لَّكُمْ وَلِأَنْعَـٰمِكُمْ","all as ˹a means of˺ sustenance for you and your animals."],[33,"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","Then, when the Deafening Blast comes to pass,"],[34,"يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ","on that Day every person will flee from their own siblings,"],[35,"وَأُمِّهِۦ وَأَبِيهِ","and ˹even˺ their mother and father,"],[36,"وَصَـٰحِبَتِهِۦ وَبَنِيهِ","and ˹even˺ their spouse and children."],[37,"لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ","For then everyone will have enough concern of their own."],[38,"وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ","On that Day ˹some˺ faces will be bright,"],[39,"ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ","laughing and rejoicing,"],[40,"وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ","while ˹other˺ faces will be dusty,"],[41,"تَرْهَقُهَا قَتَرَةٌ","cast in gloom,"],[42,"أُو۟لَـٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ","those are the disbelievers, the ˹wicked˺ sinners."]]},"81":{"n":81,"name":"At-Takwīr","ar":"التكوير","en":"Putting out ˹the Sun˺","v":[[1,"إِذَا ٱلشَّمْسُ كُوِّرَتْ","When the sun is put out,"],[2,"وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ","and when the stars fall down,"],[3,"وَإِذَا ٱلْجِبَالُ سُيِّرَتْ","and when the mountains are blown away,"],[4,"وَإِذَا ٱلْعِشَارُ عُطِّلَتْ","and when pregnant camels are left untended,"],[5,"وَإِذَا ٱلْوُحُوشُ حُشِرَتْ","and when wild beasts are gathered together,"],[6,"وَإِذَا ٱلْبِحَارُ سُجِّرَتْ","and when the seas are set on fire,"],[7,"وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ","and when the souls ˹and their bodies˺ are paired ˹once more˺,"],[8,"وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ","and when baby girls, buried alive, are asked"],[9,"بِأَىِّ ذَنۢبٍۢ قُتِلَتْ","for what crime they were put to death,"],[10,"وَإِذَا ٱلصُّحُفُ نُشِرَتْ","and when the records ˹of deeds˺ are laid open,"],[11,"وَإِذَا ٱلسَّمَآءُ كُشِطَتْ","and when the sky is stripped away,"],[12,"وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ","and when the Hellfire is fiercely flared up,"],[13,"وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ","and when Paradise is brought near,"],[14,"عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ","˹on that Day˺ each soul will know what ˹deeds˺ it has brought along."],[15,"فَلَآ أُقْسِمُ بِٱلْخُنَّسِ","I do swear by the receding stars"],[16,"ٱلْجَوَارِ ٱلْكُنَّسِ","which travel and hide,"],[17,"وَٱلَّيْلِ إِذَا عَسْعَسَ","and the night as it falls"],[18,"وَٱلصُّبْحِ إِذَا تَنَفَّسَ","and the day as it breaks!"],[19,"إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ","Indeed, this ˹Quran˺ is the Word of ˹Allah delivered by Gabriel,˺ a noble messenger-angel,"],[20,"ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍۢ","full of power, held in honour by the Lord of the Throne,"],[21,"مُّطَاعٍۢ ثَمَّ أَمِينٍۢ","obeyed there ˹in heaven˺, and trustworthy."],[22,"وَمَا صَاحِبُكُم بِمَجْنُونٍۢ","And your fellow man is not insane."],[23,"وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ","And he did see that ˹angel˺ on the clear horizon,"],[24,"وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍۢ","and he does not withhold ˹what is revealed to him of˺ the unseen."],[25,"وَمَا هُوَ بِقَوْلِ شَيْطَـٰنٍۢ رَّجِيمٍۢ","And this ˹Quran˺ is not the word of an outcast devil."],[26,"فَأَيْنَ تَذْهَبُونَ","So what ˹other˺ path would you take?"],[27,"إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَـٰلَمِينَ","Surely this ˹Quran˺ is only a reminder to the whole world,"],[28,"لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ","to whoever of you wills to take the Straight Way."],[29,"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ","But you cannot will ˹to do so˺, except by the Will of Allah, the Lord of all worlds."]]},"82":{"n":82,"name":"Al-Infiṭār","ar":"الإنفطار","en":"The ˹Sky˺ Splitting Open","v":[[1,"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ","When the sky splits open,"],[2,"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ","and when the stars fall away,"],[3,"وَإِذَا ٱلْبِحَارُ فُجِّرَتْ","and when the seas burst forth,"],[4,"وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ","and when the graves spill out,"],[5,"عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ","˹then˺ each soul will know what it has sent forth or left behind."],[6,"يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ","O humanity! What has emboldened you against your Lord, the Most Generous,"],[7,"ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","Who created you, fashioned you, and perfected your design,"],[8,"فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ","moulding you in whatever form He willed?"],[9,"كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ","But no! In fact, you deny the ˹final˺ Judgment,"],[10,"وَإِنَّ عَلَيْكُمْ لَحَـٰفِظِينَ","while you are certainly observed by vigilant,"],[11,"كِرَامًۭا كَـٰتِبِينَ","honourable angels, recording ˹everything˺."],[12,"يَعْلَمُونَ مَا تَفْعَلُونَ","They know whatever you do."],[13,"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ","Indeed, the virtuous will be in bliss,"],[14,"وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ","and the wicked will be in Hell,"],[15,"يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ","burning in it on Judgment Day,"],[16,"وَمَا هُمْ عَنْهَا بِغَآئِبِينَ","and they will have no escape from it."],[17,"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","What will make you realize what Judgment Day is?"],[18,"ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","Again, what will make you realize what Judgment Day is?"],[19,"يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ","˹It is˺ the Day no soul will be of ˹any˺ benefit to another whatsoever, for all authority on that Day belongs to Allah ˹entirely˺."]]},"83":{"n":83,"name":"Al-Muṭaffifīn","ar":"المطففين","en":"Defrauders","v":[[1,"وَيْلٌۭ لِّلْمُطَفِّفِينَ","Woe to the defrauders!"],[2,"ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ","Those who take full measure ˹when they buy˺ from people,"],[3,"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ","but give less when they measure or weigh for buyers."],[4,"أَلَا يَظُنُّ أُو۟لَـٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ","Do such people not think that they will be resurrected"],[5,"لِيَوْمٍ عَظِيمٍۢ","for a tremendous Day ,"],[6,"يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَـٰلَمِينَ","the Day ˹all˺ people will stand before the Lord of all worlds?"],[7,"كَلَّآ إِنَّ كِتَـٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ","But no! The wicked are certainly bound for Sijjîn ˹in the depths of Hell˺ ,"],[8,"وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ","and what will make you realize what Sijjîn is?,"],[9,"كِتَـٰبٌۭ مَّرْقُومٌۭ","a fate ˹already˺ sealed."],[10,"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","Woe on that Day to the deniers,"],[11,"ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ","those who deny Judgment Day!"],[12,"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ","None would deny it except every evildoing transgressor."],[13,"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ","Whenever Our revelations are recited to them, they say, “Ancient fables!”"],[14,"كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ","But no! In fact, their hearts have been stained by all ˹the evil˺ they used to commit!"],[15,"كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ","Undoubtedly, they will be sealed off from their Lord on that Day."],[16,"ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ","Moreover, they will surely burn in Hell,"],[17,"ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ","and then be told, “This is what you used to deny.”"],[18,"كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ","But no! The virtuous are certainly bound for ’Illiyûn ˹in elevated Gardens˺,"],[19,"وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ","and what will make you realize what ’Illiyûn is?,"],[20,"كِتَـٰبٌۭ مَّرْقُومٌۭ","a fate ˹already˺ sealed,"],[21,"يَشْهَدُهُ ٱلْمُقَرَّبُونَ","witnessed by those nearest ˹to Allah˺."],[22,"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ","Surely the virtuous will be in bliss,"],[23,"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","˹seated˺ on ˹canopied˺ couches, gazing around."],[24,"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ","You will recognize on their faces the glow of delight."],[25,"يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ","They will be given a drink of sealed, pure wine,"],[26,"خِتَـٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَـٰفِسُونَ","whose last sip will smell like musk. So let whoever aspires to this strive ˹diligently˺."],[27,"وَمِزَاجُهُۥ مِن تَسْنِيمٍ","And this drink’s flavour will come from Tasnîm,"],[28,"عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ","a spring from which those nearest ˹to Allah˺ will drink."],[29,"إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ","Indeed, the wicked used to laugh at the believers,"],[30,"وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ","wink to one another whenever they passed by,"],[31,"وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ","and muse ˹over these exploits˺ upon returning to their own people."],[32,"وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ","And when they saw the faithful, they would say, “These ˹people˺ are truly astray,”"],[33,"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَـٰفِظِينَ","even though they were not sent as keepers over the believers."],[34,"فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ","But on that Day the believers will be laughing at the disbelievers,"],[35,"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","as they sit on ˹canopied˺ couches, looking on."],[36,"هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ","˹The believers will be asked,˺ “Have the disbelievers ˹not˺ been paid back for what they used to do?”"]]},"84":{"n":84,"name":"Al-Inshiqāq","ar":"الإنشقاق","en":"The ˹Sky˺ Bursting Open","v":[[1,"إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ","When the sky bursts open,"],[2,"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","obeying its Lord as it must,"],[3,"وَإِذَا ٱلْأَرْضُ مُدَّتْ","and when the earth is flattened out,"],[4,"وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","and ejects ˹all˺ its contents and becomes empty,"],[5,"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","obeying its Lord as it must, ˹surely you will all be judged˺."],[6,"يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَـٰقِيهِ","O humanity! Indeed, you are labouring restlessly towards your Lord, and will ˹eventually˺ meet the consequences."],[7,"فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ","As for those who are given their record in their right hand,"],[8,"فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا","they will have an easy reckoning,"],[9,"وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا","and will return to their people joyfully."],[10,"وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ","And as for those who are given their record ˹in their left hand˺ from behind their backs,"],[11,"فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا","they will cry for ˹instant˺ destruction,"],[12,"وَيَصْلَىٰ سَعِيرًا","and will burn in the blazing Fire."],[13,"إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا","For they used to be prideful among their people,"],[14,"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","thinking they would never return ˹to Allah˺."],[15,"بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا","Yes ˹they would˺! Surely their Lord has always been All-Seeing of them."],[16,"فَلَآ أُقْسِمُ بِٱلشَّفَقِ","So, I do swear by the twilight!"],[17,"وَٱلَّيْلِ وَمَا وَسَقَ","And by the night and whatever it envelops!"],[18,"وَٱلْقَمَرِ إِذَا ٱتَّسَقَ","And by the moon when it waxes full!"],[19,"لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ","You will certainly pass from one state to another."],[20,"فَمَا لَهُمْ لَا يُؤْمِنُونَ","So what is the matter with them that they do not believe,"],[21,"وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩","and when the Quran is recited to them, they do not bow down ˹in submission˺?"],[22,"بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ","In fact, the disbelievers persist in denial."],[23,"وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ","But Allah knows best whatever they hide."],[24,"فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","So give them good news of a painful punishment."],[25,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ","But those who believe and do good will have a never-ending reward."]]},"85":{"n":85,"name":"Al-Burūj","ar":"البروج","en":"Constellations","v":[[1,"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ","By the sky full of constellations,"],[2,"وَٱلْيَوْمِ ٱلْمَوْعُودِ","and the promised Day ˹of Judgment˺,"],[3,"وَشَاهِدٍۢ وَمَشْهُودٍۢ","and the witness and what is witnessed!"],[4,"قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ","Condemned are the makers of the ditch,"],[5,"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ","the fire ˹pit˺, filled with fuel ,"],[6,"إِذْ هُمْ عَلَيْهَا قُعُودٌۭ","when they sat around it,"],[7,"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ","watching what they had ˹ordered to be˺ done to the believers,"],[8,"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ","who they resented for no reason other than belief in Allah, the Almighty, the Praiseworthy,"],[9,"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ","˹the One˺ to Whom belongs the kingdom of the heavens and earth. And Allah is a Witness over all things."],[10,"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ","Those who persecute the believing men and women and then do not repent will certainly suffer the punishment of Hell and the torment of burning."],[11,"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ","Surely those who believe and do good will have Gardens under which rivers flow. That is the greatest triumph."],[12,"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","Indeed, the ˹crushing˺ grip of your Lord is severe."],[13,"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ","˹For˺ He is certainly the One Who originates and resurrects ˹all˺."],[14,"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ","And He is the All-Forgiving, All-Loving,"],[15,"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ","Lord of the Throne, the All-Glorious,"],[16,"فَعَّالٌۭ لِّمَا يُرِيدُ","Doer of whatever He wills."],[17,"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ","Has the story of the ˹destroyed˺ forces reached you ˹O Prophet˺,"],[18,"فِرْعَوْنَ وَثَمُودَ","˹the forces of˺ Pharaoh and Thamûd?"],[19,"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ","Yet the disbelievers ˹still˺ persist in denial."],[20,"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ","But Allah encompasses them from all sides."],[21,"بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ","In fact, this is a glorious Quran,"],[22,"فِى لَوْحٍۢ مَّحْفُوظٍۭ","˹recorded˺ in a Preserved Tablet."]]},"86":{"n":86,"name":"Aṭ-Ṭāriq","ar":"الطارق","en":"The Nightly Star","v":[[1,"وَٱلسَّمَآءِ وَٱلطَّارِقِ","By the heaven and the nightly star!"],[2,"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","And what will make you realize what the nightly star is?"],[3,"ٱلنَّجْمُ ٱلثَّاقِبُ","˹It is˺ the star of piercing brightness."],[4,"إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ","There is no soul without a vigilant angel ˹recording everything˺."],[5,"فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ","Let people then consider what they were created from!"],[6,"خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ","˹They were˺ created from a spurting fluid,"],[7,"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","stemming from between the backbone and the ribcage."],[8,"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ","Surely He is fully capable of bringing them back ˹to life˺"],[9,"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","on the Day all secrets will be disclosed."],[10,"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ","Then one will have neither power nor ˹any˺ helper."],[11,"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","By the sky with its recurring cycles,"],[12,"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","and the earth with its sprouting plants!"],[13,"إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ","Surely this ˹Quran˺ is a decisive word,"],[14,"وَمَا هُوَ بِٱلْهَزْلِ","and is not to be taken lightly."],[15,"إِنَّهُمْ يَكِيدُونَ كَيْدًۭا","They are certainly devising ˹evil˺ plans,"],[16,"وَأَكِيدُ كَيْدًۭا","but I too am planning."],[17,"فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","So bear with the disbelievers ˹O Prophet˺. Let them be for ˹just˺ a little while."]]},"87":{"n":87,"name":"Al-Aʿlā","ar":"الأعلى","en":"The Most High","v":[[1,"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","Glorify the Name of your Lord, the Most High,"],[2,"ٱلَّذِى خَلَقَ فَسَوَّىٰ","Who created and ˹perfectly˺ fashioned ˹all˺,"],[3,"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","and Who ordained precisely and inspired accordingly,"],[4,"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","and Who brings forth ˹green˺ pasture,"],[5,"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","then reduces it to withered chaff."],[6,"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","We will have you recite ˹the Quran, O Prophet,˺ so you will not forget ˹any of it˺,"],[7,"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","unless Allah wills otherwise. He surely knows what is open and what is hidden."],[8,"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","We will facilitate for you the Way of Ease."],[9,"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","So ˹always˺ remind ˹with the Quran˺, ˹even˺ if the reminder is beneficial ˹only to some˺."],[10,"سَيَذَّكَّرُ مَن يَخْشَىٰ","Those in awe ˹of Allah˺ will be mindful ˹of it˺."],[11,"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","But it will be shunned by the most wretched,"],[12,"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","who will burn in the greatest Fire,"],[13,"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","where they will not ˹be able to˺ live or die."],[14,"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","Successful indeed are those who purify themselves,"],[15,"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","remember the Name of their Lord, and pray."],[16,"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","But you ˹deniers only˺ prefer the life of this world,"],[17,"وَٱلْـَٔاخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ","even though the Hereafter is far better and more lasting."],[18,"إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","This is certainly ˹mentioned˺ in the earlier Scriptures,"],[19,"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","the Scriptures of Abraham and Moses."]]},"88":{"n":88,"name":"Al-Ghāshiyah","ar":"الغاشية","en":"The Overwhelming Event","v":[[1,"هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ","Has the news of the Overwhelming Event reached you ˹O Prophet˺?"],[2,"وُجُوهٌۭ يَوْمَئِذٍ خَـٰشِعَةٌ","On that Day ˹some˺ faces will be downcast,"],[3,"عَامِلَةٌۭ نَّاصِبَةٌۭ","˹totally˺ overburdened, exhausted,"],[4,"تَصْلَىٰ نَارًا حَامِيَةًۭ","burning in a scorching Fire,"],[5,"تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍۢ","left to drink from a scalding spring."],[6,"لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍۢ","They will have no food except a foul, thorny shrub,"],[7,"لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍۢ","neither nourishing nor satisfying hunger."],[8,"وُجُوهٌۭ يَوْمَئِذٍۢ نَّاعِمَةٌۭ","On that Day ˹other˺ faces will be glowing with bliss,"],[9,"لِّسَعْيِهَا رَاضِيَةٌۭ","˹fully˺ pleased with their striving,"],[10,"فِى جَنَّةٍ عَالِيَةٍۢ","in an elevated Garden,"],[11,"لَّا تَسْمَعُ فِيهَا لَـٰغِيَةًۭ","where no idle talk will be heard."],[12,"فِيهَا عَيْنٌۭ جَارِيَةٌۭ","In it will be a running spring,"],[13,"فِيهَا سُرُرٌۭ مَّرْفُوعَةٌۭ","along with thrones raised high,"],[14,"وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ","and cups set at hand,"],[15,"وَنَمَارِقُ مَصْفُوفَةٌۭ","and ˹fine˺ cushions lined up,"],[16,"وَزَرَابِىُّ مَبْثُوثَةٌ","and ˹splendid˺ carpets spread out."],[17,"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","Do they not ever reflect on camels, how they were ˹masterfully˺ created;"],[18,"وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ","and the sky, how it was raised ˹high˺;"],[19,"وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ","and the mountains, how they were firmly set up;"],[20,"وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ","and the earth, how it was levelled out?"],[21,"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌۭ","So, ˹continue to˺ remind ˹all, O Prophet˺, for your duty is only to remind."],[22,"لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","You are not ˹there˺ to compel them ˹to believe˺."],[23,"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","But whoever turns away, persisting in disbelief,"],[24,"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","then Allah will inflict upon them the major punishment."],[25,"إِنَّ إِلَيْنَآ إِيَابَهُمْ","Surely to Us is their return,"],[26,"ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم","then surely with Us is their reckoning."]]},"89":{"n":89,"name":"Al-Fajr","ar":"الفجر","en":"Dawn","v":[[1,"وَٱلْفَجْرِ","By the dawn,"],[2,"وَلَيَالٍ عَشْرٍۢ","and the ten nights,"],[3,"وَٱلشَّفْعِ وَٱلْوَتْرِ","and the even and the odd,"],[4,"وَٱلَّيْلِ إِذَا يَسْرِ","and the night when it passes!"],[5,"هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ","Is all this ˹not˺ a sufficient oath for those who have sense?"],[6,"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","Did you not see how your Lord dealt with ’Ȃd,"],[7,"إِرَمَ ذَاتِ ٱلْعِمَادِ","˹the people˺ of Iram, with ˹their˺ great stature,"],[8,"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ","unmatched in any other land;"],[9,"وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ","and Thamûd who carved ˹their homes into˺ the rocks in the ˹Stone˺ Valley;"],[10,"وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ","and the Pharaoh of mighty structures?"],[11,"ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ","They all transgressed throughout the land,"],[12,"فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ","spreading much corruption there."],[13,"فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","So your Lord unleashed on them a scourge of punishment."],[14,"إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ","˹For˺ your Lord is truly vigilant."],[15,"فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ","Now, whenever a human being is tested by their Lord through ˹His˺ generosity and blessings, they boast, “My Lord has ˹deservedly˺ honoured me!”"],[16,"وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ","But when He tests them by limiting their provision, they protest, “My Lord has ˹undeservedly˺ humiliated me!”"],[17,"كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ","Absolutely not! In fact, you are not ˹even˺ gracious to the orphan,"],[18,"وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","nor do you urge one another to feed the poor."],[19,"وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا","And you devour ˹others’˺ inheritance greedily,"],[20,"وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا","and love wealth fervently."],[21,"كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا","Enough! When the earth is entirely crushed over and over,"],[22,"وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا","and your Lord comes ˹to judge˺ with angels, rank upon rank,"],[23,"وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ","and Hell is brought forth on that Day, this is when every ˹disbelieving˺ person will remember ˹their own sins˺. But what is the use of remembering then?"],[24,"يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى","They will cry, “I wish I had sent forth ˹something good˺ for my ˹true˺ life.”"],[25,"فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ","On that Day He will punish ˹them˺ severely, like no other,"],[26,"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ","and bind ˹them˺ tightly, like no other."],[27,"يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ","˹Allah will say to the righteous,˺ “O tranquil soul!"],[28,"ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ","Return to your Lord, well pleased ˹with Him˺ and well pleasing ˹to Him˺."],[29,"فَٱدْخُلِى فِى عِبَـٰدِى","So join My servants,"],[30,"وَٱدْخُلِى جَنَّتِى","and enter My Paradise.”"]]},"90":{"n":90,"name":"Al-Balad","ar":"البلد","en":"The City","v":[[1,"لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ","I do swear by this city ˹of Mecca˺,"],[2,"وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ","even though you ˹O Prophet˺ are subject to abuse in this city,"],[3,"وَوَالِدٍۢ وَمَا وَلَدَ","and by every parent and ˹their˺ child!"],[4,"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ","Indeed, We have created humankind in ˹constant˺ struggle."],[5,"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ","Do they think that no one has power over them,"],[6,"يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا","boasting, “I have wasted enormous wealth!”?"],[7,"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","Do they think that no one sees them?"],[8,"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","Have We not given them two eyes,"],[9,"وَلِسَانًۭا وَشَفَتَيْنِ","a tongue, and two lips;"],[10,"وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ","and shown them the two ways ˹of right and wrong˺?"],[11,"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","If only they had attempted the challenging path ˹of goodness instead˺!"],[12,"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","And what will make you realize what ˹attempting˺ the challenging path is?"],[13,"فَكُّ رَقَبَةٍ","It is to free a slave,"],[14,"أَوْ إِطْعَـٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ","or to give food in times of famine"],[15,"يَتِيمًۭا ذَا مَقْرَبَةٍ","to an orphaned relative"],[16,"أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ","or to a poor person in distress,"],[17,"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","and, above all, to be one of those who have faith and urge each other to perseverance and urge each other to compassion."],[18,"أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ","These are the people of the right."],[19,"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ","As for those who deny Our signs, they are the people of the left."],[20,"عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ","The Fire will be sealed over them."]]},"91":{"n":91,"name":"Ash-Shams","ar":"الشمس","en":"The Sun","v":[[1,"وَٱلشَّمْسِ وَضُحَىٰهَا","By the sun and its brightness,"],[2,"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","and the moon as it follows it,"],[3,"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","and the day as it unveils it,"],[4,"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","and the night as it conceals it!"],[5,"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","And by heaven and ˹the One˺ Who built it,"],[6,"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","and the earth and ˹the One˺ Who spread it!"],[7,"وَنَفْسٍۢ وَمَا سَوَّىٰهَا","And by the soul and ˹the One˺ Who fashioned it,"],[8,"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","then with ˹the knowledge of˺ right and wrong inspired it!"],[9,"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","Successful indeed is the one who purifies their soul,"],[10,"وَقَدْ خَابَ مَن دَسَّىٰهَا","and doomed is the one who corrupts it!"],[11,"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","Thamûd rejected ˹the truth˺ out of arrogance,"],[12,"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","when the most wicked of them was roused ˹to kill the she-camel˺."],[13,"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا","But the messenger of Allah warned them, “˹Do not disturb˺ Allah’s camel and her ˹turn to˺ drink!”"],[14,"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","Still they defied him and slaughtered her. So their Lord crushed them for their crime, levelling all to the ground."],[15,"وَلَا يَخَافُ عُقْبَـٰهَا","He has no fear of consequences."]]},"92":{"n":92,"name":"Al-Layl","ar":"الليل","en":"The Night","v":[[1,"وَٱلَّيْلِ إِذَا يَغْشَىٰ","By the night when it covers,"],[2,"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","and the day when it shines!"],[3,"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","And by ˹the One˺ Who created male and female!"],[4,"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","Surely the ends you strive for are diverse."],[5,"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","As for the one who is charitable, mindful ˹of Allah˺,"],[6,"وَصَدَّقَ بِٱلْحُسْنَىٰ","and ˹firmly˺ believes in the finest reward,"],[7,"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","We will facilitate for them the Way of Ease."],[8,"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","And as for the one who is stingy, indifferent ˹to Allah˺,"],[9,"وَكَذَّبَ بِٱلْحُسْنَىٰ","and ˹staunchly˺ denies the finest reward,"],[10,"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","We will facilitate for them the path of hardship."],[11,"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","And their wealth will be of no benefit to them when they tumble ˹into Hell˺."],[12,"إِنَّ عَلَيْنَا لَلْهُدَىٰ","It is certainly upon Us ˹alone˺ to show ˹the way to˺ guidance."],[13,"وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ","And surely to Us ˹alone˺ belong this life and the next."],[14,"فَأَنذَرْتُكُمْ نَارًۭا تَلَظَّىٰ","And so I have warned you of a raging Fire,"],[15,"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","in which none will burn except the most wretched ,"],[16,"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","who deny and turn away."],[17,"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","But the righteous will be spared from it ,"],[18,"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","who donate ˹some of˺ their wealth only to purify themselves,"],[19,"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ","not in return for someone’s favours,"],[20,"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","but seeking the pleasure of their Lord, the Most High."],[21,"وَلَسَوْفَ يَرْضَىٰ","They will certainly be pleased."]]},"93":{"n":93,"name":"Aḍ-Ḍuḥā","ar":"الضحى","en":"The Morning Sunlight","v":[[1,"وَٱلضُّحَىٰ","By the morning sunlight,"],[2,"وَٱلَّيْلِ إِذَا سَجَىٰ","and the night when it falls still!"],[3,"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","Your Lord ˹O Prophet˺ has not abandoned you, nor has He become hateful ˹of you˺."],[4,"وَلَلْـَٔاخِرَةُ خَيْرٌۭ لَّكَ مِنَ ٱلْأُولَىٰ","And the next life is certainly far better for you than this one."],[5,"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","And ˹surely˺ your Lord will give so much to you that you will be pleased."],[6,"أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ","Did He not find you as an orphan then sheltered you?"],[7,"وَوَجَدَكَ ضَآلًّۭا فَهَدَىٰ","Did He not find you unguided then guided you?"],[8,"وَوَجَدَكَ عَآئِلًۭا فَأَغْنَىٰ","And did He not find you needy then satisfied your needs?"],[9,"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","So do not oppress the orphan,"],[10,"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","nor repulse the beggar."],[11,"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","And proclaim the blessings of your Lord."]]},"94":{"n":94,"name":"Ash-Sharḥ","ar":"الشرح","en":"Uplifting the Heart","v":[[1,"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","Have We not uplifted your heart for you ˹O Prophet˺,"],[2,"وَوَضَعْنَا عَنكَ وِزْرَكَ","relieved you of the burden"],[3,"ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ","which weighed so heavily on your back,"],[4,"وَرَفَعْنَا لَكَ ذِكْرَكَ","and elevated your renown for you?"],[5,"فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","So, surely with hardship comes ease."],[6,"إِنَّ مَعَ ٱلْعُسْرِ يُسْرًۭا","Surely with ˹that˺ hardship comes ˹more˺ ease."],[7,"فَإِذَا فَرَغْتَ فَٱنصَبْ","So once you have fulfilled ˹your duty˺, strive ˹in devotion˺,"],[8,"وَإِلَىٰ رَبِّكَ فَٱرْغَب","turning to your Lord ˹alone˺ with hope."]]},"95":{"n":95,"name":"At-Tīn","ar":"التين","en":"The Fig","v":[[1,"وَٱلتِّينِ وَٱلزَّيْتُونِ","By the fig and the olive ˹of Jerusalem˺,"],[2,"وَطُورِ سِينِينَ","and Mount Sinai,"],[3,"وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","and this secure city ˹of Mecca˺!"],[4,"لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ","Indeed, We created humans in the best form."],[5,"ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ","But We will reduce them to the lowest of the low ˹in Hell˺,"],[6,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ","except those who believe and do good, they will have a never-ending reward."],[7,"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","Now, what makes you deny the ˹final˺ Judgment?"],[8,"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ","Is Allah not the most just of all judges?"]]},"96":{"n":96,"name":"Al-ʿAlaq","ar":"العلق","en":"The Clinging Clot ˹of Blood˺","v":[[1,"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","Read, ˹O Prophet,˺ in the Name of your Lord Who created,"],[2,"خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ","created humans from a clinging clot."],[3,"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","Read! And your Lord is the Most Generous,"],[4,"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","Who taught by the pen,"],[5,"عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ","taught humanity what they knew not."],[6,"كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ","Most certainly, one exceeds all bounds"],[7,"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","once they think they are self-sufficient."],[8,"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","˹But˺ surely to your Lord is the return ˹of all˺."],[9,"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","Have you seen the man who prevents"],[10,"عَبْدًا إِذَا صَلَّىٰٓ","a servant ˹of Ours˺ from praying?"],[11,"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","What if this ˹servant˺ is ˹rightly˺ guided,"],[12,"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","or encourages righteousness?"],[13,"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","What if that ˹man˺ persists in denial and turns away?"],[14,"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","Does he not know that Allah sees ˹all˺?"],[15,"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","But no! If he does not desist, We will certainly drag him by the forelock ,"],[16,"نَاصِيَةٍۢ كَـٰذِبَةٍ خَاطِئَةٍۢ","a lying, sinful forelock."],[17,"فَلْيَدْعُ نَادِيَهُۥ","So let him call his associates."],[18,"سَنَدْعُ ٱلزَّبَانِيَةَ","We will call the wardens of Hell."],[19,"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩","Again, no! Never obey him ˹O Prophet˺! Rather, ˹continue to˺ prostrate and draw near ˹to Allah˺."]]},"97":{"n":97,"name":"Al-Qadr","ar":"القدر","en":"The Night of Glory","v":[[1,"إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ","Indeed, ˹it is˺ We ˹Who˺ sent this ˹Quran˺ down on the Night of Glory."],[2,"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ","And what will make you realize what the Night of Glory is?"],[3,"لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ","The Night of Glory is better than a thousand months."],[4,"تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ","That night the angels and the ˹holy˺ spirit descend, by the permission of their Lord, for every ˹decreed˺ matter."],[5,"سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ","It is all peace until the break of dawn."]]},"98":{"n":98,"name":"Al-Bayyinah","ar":"البينة","en":"The Clear Proof","v":[[1,"لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ","The disbelievers from the People of the Book and the polytheists were not going to desist ˹from disbelief˺ until the clear proof came to them:"],[2,"رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ","a messenger from Allah, reciting scrolls of ˹utmost˺ purity,"],[3,"فِيهَا كُتُبٌۭ قَيِّمَةٌۭ","containing upright commandments."],[4,"وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ","It was not until this clear proof came to the People of the Book that they became divided ˹about his prophethood˺,"],[5,"وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ","even though they were only commanded to worship Allah ˹alone˺ with sincere devotion to Him in all uprightness, establish prayer, and pay alms-tax. That is the upright Way."],[6,"إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ","Indeed, those who disbelieve from the People of the Book and the polytheists will be in the Fire of Hell, to stay there forever. They are the worst of ˹all˺ beings."],[7,"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ","Indeed, those who believe and do good, they are the best of ˹all˺ beings."],[8,"جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ","Their reward with their Lord will be Gardens of Eternity, under which rivers flow, to stay there for ever and ever. Allah is pleased with them and they are pleased with Him. This is ˹only˺ for those in awe of their Lord."]]},"99":{"n":99,"name":"Az-Zalzalah","ar":"الزلزلة","en":"The ˹Ultimate˺ Quake","v":[[1,"إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","When the earth is shaken ˹in˺ its ultimate quaking,"],[2,"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","and when the earth throws out ˹all˺ its contents,"],[3,"وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا","and humanity cries, “What is wrong with it?”,"],[4,"يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا","on that Day the earth will recount everything,"],[5,"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","having been inspired by your Lord ˹to do so˺."],[6,"يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ","On that Day people will proceed in separate groups to be shown ˹the consequences of˺ their deeds."],[7,"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","So whoever does an atom’s weight of good will see it."],[8,"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ","And whoever does an atom’s weight of evil will see it."]]},"100":{"n":100,"name":"Al-ʿĀdiyāt","ar":"العاديات","en":"The Galloping ˹Horses˺","v":[[1,"وَٱلْعَـٰدِيَـٰتِ ضَبْحًۭا","By the galloping, panting horses,"],[2,"فَٱلْمُورِيَـٰتِ قَدْحًۭا","striking sparks of fire ˹with their hoofs˺,"],[3,"فَٱلْمُغِيرَٰتِ صُبْحًۭا","launching raids at dawn,"],[4,"فَأَثَرْنَ بِهِۦ نَقْعًۭا","stirring up ˹clouds of˺ dust,"],[5,"فَوَسَطْنَ بِهِۦ جَمْعًا","and penetrating into the heart of enemy lines!"],[6,"إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌۭ","Surely humankind is ungrateful to their Lord,"],[7,"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ","and they certainly attest to this,"],[8,"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ","and they are truly extreme in their love of ˹worldly˺ gains."],[9,"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","Do they not know that when the contents of the graves will be spilled out,"],[10,"وَحُصِّلَ مَا فِى ٱلصُّدُورِ","and the secrets of the hearts will be laid bare ,"],[11,"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ","surely their Lord is All-Aware of them on that Day."]]},"101":{"n":101,"name":"Al-Qāriʿah","ar":"القارعة","en":"The Striking Disaster","v":[[1,"ٱلْقَارِعَةُ","The Striking Disaster!"],[2,"مَا ٱلْقَارِعَةُ","What is the Striking Disaster?"],[3,"وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ","And what will make you realize what the Striking Disaster is?"],[4,"يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ","˹It is˺ the Day people will be like scattered moths,"],[5,"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ","and the mountains will be like carded wool."],[6,"فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","So as for those whose scale is heavy ˹with good deeds˺,"],[7,"فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ","they will be in a life of bliss."],[8,"وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","And as for those whose scale is light,"],[9,"فَأُمُّهُۥ هَاوِيَةٌۭ","their home will be the abyss."],[10,"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","And what will make you realize what that is?"],[11,"نَارٌ حَامِيَةٌۢ","˹It is˺ a scorching Fire."]]},"102":{"n":102,"name":"At-Takāthur","ar":"التكاثر","en":"Competition for More ˹Gains˺","v":[[1,"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ","Competition for more ˹gains˺ diverts you ˹from Allah˺,"],[2,"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ","until you end up in ˹your˺ graves."],[3,"كَلَّا سَوْفَ تَعْلَمُونَ","But no! You will soon come to know."],[4,"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","Again, no! You will soon come to know."],[5,"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ","Indeed, if you were to know ˹your fate˺ with certainty, ˹you would have acted differently˺."],[6,"لَتَرَوُنَّ ٱلْجَحِيمَ","˹But˺ you will surely see the Hellfire."],[7,"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ","Again, you will surely see it with the eye of certainty."],[8,"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ","Then, on that Day, you will definitely be questioned about ˹your worldly˺ pleasures."]]},"103":{"n":103,"name":"Al-ʿAṣr","ar":"العصر","en":"The ˹Passage of˺ Time","v":[[1,"وَٱلْعَصْرِ","By the ˹passage of˺ time!"],[2,"إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ","Surely humanity is in ˹grave˺ loss,"],[3,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ","except those who have faith, do good, and urge each other to the truth, and urge each other to perseverance."]]},"104":{"n":104,"name":"Al-Humazah","ar":"الهمزة","en":"The Backbiters","v":[[1,"وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ","Woe to every backbiter, slanderer,"],[2,"ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ","who amasses wealth ˹greedily˺ and counts it ˹repeatedly˺,"],[3,"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","thinking that their wealth will make them immortal!"],[4,"كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ","Not at all! Such a person will certainly be tossed into the Crusher."],[5,"وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ","And what will make you realize what the Crusher is?"],[6,"نَارُ ٱللَّهِ ٱلْمُوقَدَةُ","˹It is˺ Allah’s kindled Fire,"],[7,"ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ","which rages over the hearts."],[8,"إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ","It will be sealed over them,"],[9,"فِى عَمَدٍۢ مُّمَدَّدَةٍۭ","˹tightly secured˺ with long braces."]]},"105":{"n":105,"name":"Al-Fīl","ar":"الفيل","en":"The Elephant","v":[[1,"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ","Have you not seen ˹O Prophet˺ how your Lord dealt with the Army of the Elephant?"],[2,"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ","Did He not frustrate their scheme?"],[3,"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","For He sent against them flocks of birds,"],[4,"تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ","that pelted them with stones of baked clay,"],[5,"فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ","leaving them like chewed up straw."]]},"106":{"n":106,"name":"Quraysh","ar":"قريش","en":"˹The People of˺ Quraysh","v":[[1,"لِإِيلَـٰفِ قُرَيْشٍ","˹At least˺ for ˹the favour of˺ making Quraysh habitually secure,"],[2,"إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ","secure in their trading caravan ˹to Yemen˺ in the winter and ˹Syria˺ in the summer,"],[3,"فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ","let them worship the Lord of this ˹Sacred˺ House,"],[4,"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ","Who has fed them against hunger and made them secure against fear."]]},"107":{"n":107,"name":"Al-Māʿūn","ar":"الماعون","en":"˹Simplest˺ Aid","v":[[1,"أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ","Have you seen the one who denies the ˹final˺ Judgment?"],[2,"فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ","That is the one who repulses the orphan,"],[3,"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","and does not encourage the feeding of the poor."],[4,"فَوَيْلٌۭ لِّلْمُصَلِّينَ","So woe to those ˹hypocrites˺ who pray"],[5,"ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","yet are unmindful of their prayers;"],[6,"ٱلَّذِينَ هُمْ يُرَآءُونَ","those who ˹only˺ show off,"],[7,"وَيَمْنَعُونَ ٱلْمَاعُونَ","and refuse to give ˹even the simplest˺ aid."]]},"108":{"n":108,"name":"Al-Kawthar","ar":"الكوثر","en":"Abundant Goodness","v":[[1,"إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ","Indeed, We have granted you ˹O Prophet˺ abundant goodness."],[2,"فَصَلِّ لِرَبِّكَ وَٱنْحَرْ","So pray and sacrifice to your Lord ˹alone˺."],[3,"إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ","Only the one who hates you is truly cut off ˹from any goodness˺."]]},"109":{"n":109,"name":"Al-Kāfirūn","ar":"الكافرون","en":"The Disbelievers","v":[[1,"قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ","Say, ˹O Prophet,˺ “O you disbelievers!"],[2,"لَآ أَعْبُدُ مَا تَعْبُدُونَ","I do not worship what you worship,"],[3,"وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ","nor do you worship what I worship."],[4,"وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ","I will never worship what you worship,"],[5,"وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ","nor will you ever worship what I worship."],[6,"لَكُمْ دِينُكُمْ وَلِىَ دِينِ","You have your way, and I have my Way.”"]]},"110":{"n":110,"name":"An-Naṣr","ar":"النصر","en":"The ˹Ultimate˺ Help","v":[[1,"إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","When Allah’s ˹ultimate˺ help comes and the victory ˹over Mecca is achieved˺,"],[2,"وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا","and you ˹O Prophet˺ see the people embracing Allah’s Way in crowds,"],[3,"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا","then glorify the praises of your Lord and seek His forgiveness, for certainly He is ever Accepting of Repentance."]]},"111":{"n":111,"name":"Al-Masad","ar":"المسد","en":"The Palm-Fibre Rope","v":[[1,"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ","May the hands of Abu Lahab perish, and he ˹himself˺ perish!"],[2,"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ","Neither his wealth nor ˹worldly˺ gains will benefit him."],[3,"سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ","He will burn in a flaming Fire,"],[4,"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ","and ˹so will˺ his wife, the carrier of ˹thorny˺ kindling,"],[5,"فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ","around her neck will be a rope of palm-fibre."]]},"112":{"n":112,"name":"Al-Ikhlāṣ","ar":"الإخلاص","en":"Purity of Faith","v":[[1,"قُلْ هُوَ ٱللَّهُ أَحَدٌ","Say, ˹O Prophet,˺ “He is Allah, One ˹and Indivisible˺;"],[2,"ٱللَّهُ ٱلصَّمَدُ","Allah, the Sustainer ˹needed by all˺."],[3,"لَمْ يَلِدْ وَلَمْ يُولَدْ","He has never had offspring, nor was He born."],[4,"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","And there is none comparable to Him.”"]],"tr":["Qul Huwallāhu Aḥad.","Allāhuṣ-Ṣamad.","Lam yalid wa lam yūlad.","Wa lam yakul-lahū kufuwan aḥad."]},"113":{"n":113,"name":"Al-Falaq","ar":"الفلق","en":"The Daybreak","v":[[1,"قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","Say, ˹O Prophet,˺ “I seek refuge in the Lord of the daybreak"],[2,"مِن شَرِّ مَا خَلَقَ","from the evil of whatever He has created,"],[3,"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","and from the evil of the night when it grows dark,"],[4,"وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ","and from the evil of those ˹witches casting spells by˺ blowing onto knots,"],[5,"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","and from the evil of an envier when they envy.”"]],"tr":["Qul aʿūdhu bi-Rabbil-falaq.","Min sharri mā khalaq.","Wa min sharri ghāsiqin idhā waqab.","Wa min sharrin-naffāthāti fil-ʿuqad.","Wa min sharri ḥāsidin idhā ḥasad."]},"114":{"n":114,"name":"An-Nās","ar":"الناس","en":"Humankind","v":[[1,"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","Say, ˹O Prophet,˺ “I seek refuge in the Lord of humankind,"],[2,"مَلِكِ ٱلنَّاسِ","the Master of humankind,"],[3,"إِلَـٰهِ ٱلنَّاسِ","the God of humankind,"],[4,"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","from the evil of the lurking whisperer,"],[5,"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","who whispers into the hearts of humankind,"],[6,"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","from among jinn and humankind.”"]],"tr":["Qul aʿūdhu bi-Rabbin-nās.","Malikin-nās.","Ilāhin-nās.","Min sharril-waswāsil-khannās.","Alladhī yuwaswisu fī ṣudūrin-nās.","Minal-jinnati wan-nās."]}}};
window.HAD={"bukhari:1":{"ar":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى…","en":"The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 1","refa":"صحيح البخاري 1","url":"https://sunnah.com/bukhari:1"},"bukhari:8":{"ar":"بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ.","en":"Islam is based on (the following) five (principles): 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah's Messenger (ﷺ). 2. To offer the (compulsory congregational) prayers dutifully and perfectly. 3. To pay Zakat (i.e. obligatory charity) . 4. To perform Hajj. (i.e. Pilgrimage to Mecca) 5. To observe fast during the month of Ramadan.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 8","refa":"صحيح البخاري 8","url":"https://sunnah.com/bukhari:8"},"bukhari:12":{"ar":"تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ.","en":"To feed (the poor) and greet those whom you know and those whom you do not know.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 12","refa":"صحيح البخاري 12","url":"https://sunnah.com/bukhari:12"},"bukhari:13":{"ar":"لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ.","en":"None of you will have faith till he wishes for his (Muslim) brother what he likes for himself.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 13","refa":"صحيح البخاري 13","url":"https://sunnah.com/bukhari:13"},"bukhari:159":{"ar":"رَأَى عُثْمَانَ بْنَ عَفَّانَ دَعَا بِإِنَاءٍ، فَأَفْرَغَ عَلَى كَفَّيْهِ ثَلاَثَ مِرَارٍ فَغَسَلَهُمَا، ثُمَّ أَدْخَلَ يَمِينَهُ فِي الإِنَاءِ فَمَضْمَضَ، وَاسْتَنْشَقَ، ثُمَّ غَسَلَ وَجْهَهُ ثَلاَثًا، وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلاَثَ مِرَارٍ، ثُمَّ مَسَحَ بِرَأْسِهِ، ثُمَّ غَسَلَ رِجْلَيْهِ ثَلاَثَ مِرَارٍ إِلَى الْكَعْبَيْنِ.","en":"I saw 'Uthman bin 'Affan asking for a tumbler of water (and when it was brought) he poured water over his hands and washed them thrice and then put his right hand in the water container and rinsed his mouth, washed his nose by putting water in it and then blowing it out. then he washed his face and forearms up to the elbows thrice, passed his wet hands over his head and washed his feet up to the ankles thrice.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 159","refa":"صحيح البخاري 159","url":"https://sunnah.com/bukhari:159"},"bukhari:631":{"ar":"صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي.","en":"Pray as you have seen me praying.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 631","refa":"صحيح البخاري 631","url":"https://sunnah.com/bukhari:631"},"bukhari:652":{"ar":"بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ فَأَخَّرَهُ، فَشَكَرَ اللَّهُ لَهُ، فَغَفَرَ لَهُ.","en":"While a man was going on a way, he saw a thorny branch and removed it from the way and Allah became pleased by his action and forgave him for that.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 652","refa":"صحيح البخاري 652","url":"https://sunnah.com/bukhari:652"},"bukhari:2363":{"ar":"بَيْنَا رَجُلٌ يَمْشِي فَاشْتَدَّ عَلَيْهِ الْعَطَشُ، فَنَزَلَ بِئْرًا فَشَرِبَ مِنْهَا، ثُمَّ خَرَجَ فَإِذَا هُوَ بِكَلْبٍ يَلْهَثُ، يَأْكُلُ الثَّرَى مِنَ الْعَطَشِ، فَقَالَ لَقَدْ بَلَغَ هَذَا مِثْلُ الَّذِي بَلَغَ بِي فَمَلأَ خُفَّهُ ثُمَّ أَمْسَكَهُ بِفِيهِ، ثُمَّ رَقِيَ، فَسَقَى الْكَلْبَ فَشَكَرَ اللَّهُ لَهُ، فَغَفَرَ لَهُ.","en":"While a man was walking he felt thirsty and went down a well and drank water from it. On coming out of it, he saw a dog panting and eating mud because of excessive thirst. The man said, 'This (dog) is suffering from the same problem as that of mine. So he (went down the well), filled his shoe with water, caught hold of it with his teeth and climbed up and watered the dog. Allah thanked him for his (good) deed and forgave him.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 2363","refa":"صحيح البخاري 2363","url":"https://sunnah.com/bukhari:2363"},"bukhari:2989":{"ar":"وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ…","en":"(saying) a good word is also Sadaqa…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 2989","refa":"صحيح البخاري 2989","url":"https://sunnah.com/bukhari:2989"},"bukhari:5027":{"ar":"خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ.","en":"The best among you (Muslims) are those who learn the Qur'an and teach it.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 5027","refa":"صحيح البخاري 5027","url":"https://sunnah.com/bukhari:5027"},"bukhari:5376":{"ar":"يَا غُلاَمُ سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ.","en":"O boy! Mention the Name of Allah and eat with your right hand, and eat of the dish what is nearer to you.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 5376","refa":"صحيح البخاري 5376","url":"https://sunnah.com/bukhari:5376"},"bukhari:5971":{"ar":"جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ مَنْ أَحَقُّ بِحُسْنِ صَحَابَتِي قَالَ أُمُّكَ . قَالَ ثُمَّ مَنْ قَالَ أُمُّكَ . قَالَ ثُمَّ مَنْ قَالَ أُمُّكَ . قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أَبُوكَ.","en":"A man came to Allah's Messenger (ﷺ) and said, O Allah's Messenger (ﷺ)! Who is more entitled to be treated with the best companionship by me? The Prophet (ﷺ) said, Your mother. The man said. Who is next? The Prophet said, Your mother. The man further said, Who is next? The Prophet (ﷺ) said, Your mother. The man asked for the fourth time, Who is next? The Prophet (ﷺ) said, Your father.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 5971","refa":"صحيح البخاري 5971","url":"https://sunnah.com/bukhari:5971"},"bukhari:5997":{"ar":"مَنْ لاَ يَرْحَمُ لاَ يُرْحَمُ.","en":"Whoever is not merciful to others will not be treated mercifully.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 5997","refa":"صحيح البخاري 5997","url":"https://sunnah.com/bukhari:5997"},"bukhari:6018":{"ar":"مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلاَ يُؤْذِ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ.","en":"Anybody who believes in Allah and the Last Day should not harm his neighbor, and anybody who believes in Allah and the Last Day should entertain his guest generously and anybody who believes in Allah and the Last Day should talk what is good or keep quiet.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6018","refa":"صحيح البخاري 6018","url":"https://sunnah.com/bukhari:6018"},"bukhari:6035":{"ar":"إِنَّ خِيَارَكُمْ أَحَاسِنُكُمْ أَخْلاَقًا.","en":"The best among you are the best in character.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6035","refa":"صحيح البخاري 6035","url":"https://sunnah.com/bukhari:6035"},"bukhari:6094":{"ar":"إِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَإِنَّ الرَّجُلَ لَيَصْدُقُ حَتَّى يَكُونَ صِدِّيقًا…","en":"Truthfulness leads to righteousness, and righteousness leads to Paradise. And a man keeps on telling the truth until he becomes a truthful person…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6094","refa":"صحيح البخاري 6094","url":"https://sunnah.com/bukhari:6094"},"bukhari:6116":{"ar":"أَنَّ رَجُلاً، قَالَ لِلنَّبِيِّ صلى الله عليه وسلم أَوْصِنِي. قَالَ لاَ تَغْضَبْ.","en":"A man said to the Prophet (ﷺ) , Advise me! The Prophet (ﷺ) said, Do not become angry and furious.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6116","refa":"صحيح البخاري 6116","url":"https://sunnah.com/bukhari:6116"},"bukhari:6224":{"ar":"إِذَا عَطَسَ أَحَدُكُمْ فَلْيَقُلِ الْحَمْدُ لِلَّهِ. وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ يَرْحَمُكَ اللَّهُ. فَإِذَا قَالَ لَهُ يَرْحَمُكَ اللَّهُ. فَلْيَقُلْ يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ.","en":"If anyone of you sneezes, he should say 'Al-Hamduli l-lah' (Praise be to Allah), and his (Muslim) brother or companion should say to him, 'Yar-hamuka-l-lah' (May Allah bestow his Mercy on you). When the latter says 'Yar-hamuka-llah, the former should say, 'Yahdikumul-lah wa Yuslih balakum' (May Allah give you guidance and improve your condition).","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6224","refa":"صحيح البخاري 6224","url":"https://sunnah.com/bukhari:6224"},"bukhari:6247":{"ar":"أَنَّهُ مَرَّ عَلَى صِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ وَقَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يَفْعَلُهُ.","en":"That he passed by a group of boys and greeted them and said, The Prophet (ﷺ) used to do so.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6247","refa":"صحيح البخاري 6247","url":"https://sunnah.com/bukhari:6247"},"bukhari:6406":{"ar":"كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ، سُبْحَانَ اللَّهِ الْعَظِيمِ، سُبْحَانَ اللَّهِ وَبِحَمْدِهِ.","en":"There are two expressions which are very easy for the tongue to say, but they are very heavy in the balance and are very dear to The Beneficent (Allah), and they are, 'Subhan Allah Al- `Azim and 'Subhan Allah wa bihamdihi.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6406","refa":"صحيح البخاري 6406","url":"https://sunnah.com/bukhari:6406"},"bukhari:6464":{"ar":"وَأَنَّ أَحَبَّ الأَعْمَالِ أَدْوَمُهَا إِلَى اللَّهِ، وَإِنْ قَلَّ…","en":"The most beloved deed to Allah is the most regular and constant even if it were little…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ al-Bukhārī 6464","refa":"صحيح البخاري 6464","url":"https://sunnah.com/bukhari:6464"},"muslim:8":{"ar":"أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ.","en":"That you affirm your faith in Allah, in His angels, in His Books, in His Apostles, in the Day of Judgment, and you affirm your faith in the Divine Decree about good and evil.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 8","refa":"صحيح مسلم 8","url":"https://sunnah.com/muslim:8"},"muslim:54":{"ar":"أَوَلاَ أَدُلُّكُمْ عَلَى شَىْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلاَمَ بَيْنَكُمْ.","en":"Should I not direct you to a thing which, if you do, will foster love amongst you: (i. e.) give currency to (the practice of paying salutation to one another by saying) as-salamu alaikum.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 54","refa":"صحيح مسلم 54","url":"https://sunnah.com/muslim:54"},"muslim:223":{"ar":"الطُّهُورُ شَطْرُ الإِيمَانِ…","en":"Cleanliness is half of faith…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 223","refa":"صحيح مسلم 223","url":"https://sunnah.com/muslim:223"},"muslim:2594":{"ar":"إِنَّ الرِّفْقَ لاَ يَكُونُ فِي شَىْءٍ إِلاَّ زَانَهُ وَلاَ يُنْزَعُ مِنْ شَىْءٍ إِلاَّ شَانَهُ.","en":"Kindness is not to be found in anything but that it adds to its beauty and it is not withdrawn from anything but it makes it defective.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 2594","refa":"صحيح مسلم 2594","url":"https://sunnah.com/muslim:2594"},"muslim:2626":{"ar":"لاَ تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ.","en":"Don't consider anything insignificant out of good things even if it is that you meet your brother with a cheerful countenance.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 2626","refa":"صحيح مسلم 2626","url":"https://sunnah.com/muslim:2626"},"muslim:2699":{"ar":"وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ…","en":"He who treads the path in search of knowledge, Allah would make that path easy, leading to Paradise for him…","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 2699","refa":"صحيح مسلم 2699","url":"https://sunnah.com/muslim:2699"},"muslim:2734":{"ar":"إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا.","en":"Allah is pleased with His servant who says: Al-Hamdu lillah while taking a morsel of food and while drinking.","g":"Ṣaḥīḥ","ref":"Ṣaḥīḥ Muslim 2734","refa":"صحيح مسلم 2734","url":"https://sunnah.com/muslim:2734"},"tirmidhi:1956":{"ar":"تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ لَكَ صَدَقَةٌ…","en":"Your smiling in the face of your brother is charity…","g":"Ṣaḥīḥ (al-Albānī)","ref":"Jāmiʿ at-Tirmidhī 1956","refa":"جامع الترمذي 1956","url":"https://sunnah.com/tirmidhi:1956"}};
window.DUA={"wake":{"id":1,"when":["When I wake up","عند الاستيقاظ"],"ar":"الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ","tr":"Alḥamdu lillāhil-ladhī 'aḥyānā ba`da mā 'amātanā wa 'ilayhin-nushūr.","en":"Praise is to Allah Who gives us life after He has caused us to die and to Him is the return.","ref":"Ḥiṣn al-Muslim 1","url":"https://sunnah.com/hisn:1"},"dress":{"id":5,"when":["When I get dressed","عند لبس الثوب"],"ar":"الْحَمْدُ للَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّة","tr":"Alḥamdu lillāhil-ladhī kasānī hādhā (aththawba) wa razaqanīhi min ghayri hawlim-minnī wa lā quwwah.","en":"Praise is to Allah Who has clothed me with this (garment) and provided it for me, though I was powerless myself and incapable","ref":"Ḥiṣn al-Muslim 5","url":"https://sunnah.com/hisn:5"},"toilet-in":{"id":10,"when":["Before the toilet","قبل دخول الخلاء"],"ar":"بِسْمِ اللَّهِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبائِث","tr":"Bismillāhi Allāhumma 'innī 'a`ūdhu bika minal-khubthi walkhabā'ith.","en":"In the Name of Allah. O Allah, I seek protection in You from evil and the evil ones (or, from the evil male and female Jinn).","ref":"Ḥiṣn al-Muslim 10","url":"https://sunnah.com/hisn:10"},"toilet-out":{"id":11,"when":["After the toilet","بعد الخروج من الخلاء"],"ar":"غُفْرَانَكَ","tr":"Ghufrānaka","en":"I seek Your forgiveness.","ref":"Ḥiṣn al-Muslim 11","url":"https://sunnah.com/hisn:11"},"wudu-before":{"id":12,"when":["Before wuḍūʾ","قبل الوضوء"],"ar":"بِسْمِ اللَّهِ","tr":"Bismillāhi","en":"In the Name of Allah","ref":"Ḥiṣn al-Muslim 12","url":"https://sunnah.com/hisn:12"},"wudu-after":{"id":13,"when":["After wuḍūʾ","بعد الوضوء"],"ar":"أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ","tr":"'Ash-hadu 'an lā 'ilāha 'illallāhu waḥdahu lā sharīka lahu wa 'ash-hadu 'anna Muḥammadan `abduhu wa Rasūluhu.","en":"I bear witness that none has the right to be worshipped but Allah alone, Who has no partner; and I bear witness that Muhammad is His slave and His Messenger.","ref":"Ḥiṣn al-Muslim 13","url":"https://sunnah.com/hisn:13"},"out":{"id":16,"when":["Leaving home","عند الخروج من البيت"],"ar":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَاَ حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ","tr":"Bismillāhi, tawakkaltu `alallāhi, wa lā ḥawla wa lā quwwata illā billāh.","en":"In the Name of Allah, I have placed my trust in Allah, there is no might and no power except by Allah.","ref":"Ḥiṣn al-Muslim 16","url":"https://sunnah.com/hisn:16"},"in":{"id":18,"when":["Coming home","عند دخول البيت"],"ar":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","tr":"Bismillāhi walajnā, wa bismillāhi kharajnā, wa `ala Rabbinā tawakkalnā","en":"In the Name of Allah we enter, in the Name of Allah we leave, and upon our Lord we depend.","ref":"Ḥiṣn al-Muslim 18","url":"https://sunnah.com/hisn:18"},"eat":{"id":178,"when":["Before I eat","قبل الطعام"],"ar":"إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً فَلْيَقُلْ بِسْمِ اللَّهِ، فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ بسمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ","tr":"When anyone of you begins eating, say:Bismillāh. And if you forget then when you remember, say: Bismillāhi fī awwalihi wa ākhirih.","en":"When anyone of you begins eating, say: With the Name of Allah. And if you forget then, when you remember, say: With the Name of Allah, in the beginning, and in the end.","ref":"Ḥiṣn al-Muslim 178","url":"https://sunnah.com/hisn:178","say":"بِسْمِ اللَّهِ"},"ate":{"id":180,"when":["After I eat","بعد الطعام"],"ar":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ","tr":"Alhamdu lillāhi ‘l-ladhī aṭ`amanī hādhā, wa razaqanīhi min ghayri ḥawlin minnī wa lā quwwah.","en":"Praise is to Allah Who has given me this food, and sustained me with it though I was unable to do it and powerless.","ref":"Ḥiṣn al-Muslim 180","url":"https://sunnah.com/hisn:180"},"sneeze":{"id":188,"when":["When I sneeze","عند العطاس"],"ar":"إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ الْحَمْدُ لِلَّهِ، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ اللَّهُ، فَإِذَا قَالَ لَهُ: يَرحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ","tr":"When you sneeze, then say:Alḥamdulillāh Your companion should say: Yarḥamukallāh When someone says Yarḥamukallāh to you then you should say: Yahdīkumu ‘llāhu wa yuṣliḥu bālakum.","en":"When you sneeze, then say: All praises and thanks are to Allah. Your companion should say: May Allah have mercy upon you. When someone says Yarḥamukallāh to you then you should say: May Allah guide you and set your affairs in order.","ref":"Ḥiṣn al-Muslim 188","url":"https://sunnah.com/hisn:188","say":"الْحَمْدُ لِلَّهِ"},"sleep":{"id":105,"when":["Before I sleep","قبل النوم"],"ar":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","tr":"Bismika Allāhumma amūtu wa aḥyā.","en":"In Your Name, O Allah, I die and I live.","ref":"Ḥiṣn al-Muslim 105","url":"https://sunnah.com/hisn:105"},"rain":{"id":172,"when":["When it rains","عند نزول المطر"],"ar":"اللَّهُمَّ صَيِّباً نَافِعاً","tr":"Allāhumma ṣayyiban nāfi`a.","en":"O Allah, (bring) beneficial rain clouds.","ref":"Ḥiṣn al-Muslim 172","url":"https://sunnah.com/hisn:172"},"angry":{"id":193,"when":["When I am angry","عند الغضب"],"ar":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tr":"A`ūdhu billāhi minash-Shayṭānir-rajīm.","en":"I seek refuge in Allah from Satan the outcast.","ref":"Ḥiṣn al-Muslim 193","url":"https://sunnah.com/hisn:193"}};
window.SAY={"t-akbar":{"ar":"اللَّهُ أَكْبَرُ","tr":"Allāhu akbar.","en":"Allah is the Most Great.","ref":"Ṣaḥīḥ Muslim 597"},"p-ruku":{"ar":"سُبْحانَ رَبِّيَ الْعَظِيمِ","tr":"Subḥāna Rabbiyal-ʿAẓīm.","en":"Glory to my Lord the Exalted","ref":"Sunan Abī Dāwūd 871"},"p-sami":{"ar":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ","tr":"Samiʿallāhu liman ḥamidah.","en":"Allah hears whoever praises Him.","ref":"Ṣaḥīḥ al-Bukhārī 789"},"p-sujud":{"ar":"سُبْحَانَ رَبِّيَ الأَعْلَى","tr":"Subḥāna Rabbiya ‘l-aʿlā.","en":"Glory is to my Lord, the Most High.","ref":"Sunan Abī Dāwūd 871"},"p-jalsah":{"ar":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي","tr":"Rabbi’ghfir lī, Rabbi’ghfir lī.","en":"Lord, forgive me. My Lord, forgive me.","ref":"Sunan Ibn Mājah 897"},"t-subhan":{"ar":"سُبْحَانَ اللَّهِ","tr":"Subḥānallāh.","en":"Glory is to Allah.","ref":"Ṣaḥīḥ Muslim 597"},"t-hamd":{"ar":"الْحَمْدُ لِلَّهِ","tr":"Al-ḥamdu lillāh.","en":"Praise is to Allah.","ref":"Ṣaḥīḥ Muslim 597"},"hawqala":{"ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Lā ḥawla wa lā quwwata illā billāh.","en":"There is no power and no might except by Allah.","ref":"Ṣaḥīḥ al-Bukhārī 6384"},"subhan":{"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"Subḥānallāhi wa biḥamdih.","en":"Glory is to Allah and praise is to Him.","ref":"Ṣaḥīḥ Muslim 2692"},"p-rabbana":{"ar":"رَبَّنَا وَلَكَ الْحَمْدُ","tr":"Rabbanā wa lakal-ḥamd.","en":"Our Lord, praise is Yours.","ref":"Ṣaḥīḥ al-Bukhārī 799"},"p-tashahhud":{"ar":"التَّحِيَّاتُ لِلَّهِ، وَالصَّلَواتُ، وَالطَّيِّباتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ","tr":"Attaḥiyyātu lillāhi waṣṣalawātu, waṭṭayyibāt, assalāmu ʿalayka 'ayyuhan-Nabiyyu wa raḥmatullāhi wa barakātuh, assalāmu ʿalaynā wa ʿalā ‘ibādillāhiṣ-ṣāliḥīn. 'Ash-hadu 'an lā 'ilāha 'illallāh wa 'ash-hadu 'anna Muḥammadan ʿabduhu wa rasūluh.","en":"All greetings of humility are for Allah, and all prayers and goodness. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous slaves of Allah. I bear witness that there is none worthy of worship but Allah, and I bear witness that Muhammad is His slave and His Messenger.","ref":"Ṣaḥīḥ al-Bukhārī 831"},"a-salawat":{"ar":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","tr":"Allāhumma ṣalli ʿalā Muḥammadinwa ʿalā ’āli Muḥammadin, kamā ṣallayta ʿalā 'Ibrāhīma wa ʿalā ’āli 'Ibrāhīma, 'innaka ḥamīdum-majīd. Allāhumma bārik ʿalā Muḥammadin wa ʿalā ’āli Muḥammadin, kamā bārakta ʿalā 'Ibrāhīma wa ʿalā 'āli 'Ibrāhīma, 'innaka ḥamīdum-majīd.","en":"O Allah, bestow Your favor on Muhammad and on the family of Muhammad as You have bestowed Your favor on Ibrahim and on the family of Ibrahim, You are Praiseworthy, Most Glorious. O Allah, bless Muhammad and the family of Muhammad as You have blessed Ibrahim and the family of Ibrahim, You are Praiseworthy, Most Glorious.","ref":"Ṣaḥīḥ al-Bukhārī 3370"},"taslim":{"ar":"السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ","tr":"As-salāmu ʿalaykum wa raḥmatullāh.","en":"Peace be upon you, and mercy of Allah.","ref":"Sunan Abī Dāwūd 996"}};
